<script setup lang="ts">
import { onMounted,reactive,ref } from 'vue'
import { useRouter } from 'vue-router'
import { orderServiceApi } from '@/api/orderService'
import { useAuthStore } from '@/stores/auth'
const router=useRouter(),auth=useAuthStore(),rows=ref<any[]>([]),total=ref(0),loading=ref(false);const q=reactive<any>({page:1,size:20,keyword:'',status:'',productType:'',deliveryMode:''});const data=(r:any)=>r.data.data
async function load(){loading.value=true;try{const d=data(await orderServiceApi.services(q));rows.value=d.items||[];total.value=d.total||0}finally{loading.value=false}}
function preview(r:any,action:'renew'|'suspend'|'resume'|'terminate'){
 router.push({path:'/service-changes',query:{serviceId:String(r.id),action}})
}
onMounted(load)
</script>
<template><div class="page"><div class="head"><div><h2>服务实例</h2><p>服务实例固化客户、产品、套餐、交付方式和实际资源引用；资源选择规则由代码内置策略执行。</p></div><el-button v-if="auth.hasPermission('service:provision')" type="primary" @click="router.push('/service-provision')">服务开通</el-button></div><el-card shadow="never"><div class="filters"><el-input v-model="q.keyword" placeholder="服务号/客户" clearable/><el-select v-model="q.productType" placeholder="产品类型" clearable><el-option v-for="x in ['SHORT_IP','LONG_IP','EXCLUSIVE_IP','VPN','TUNNEL']" :key="x" :label="x" :value="x"/></el-select><el-select v-model="q.deliveryMode" placeholder="交付方式" clearable><el-option label="自有资源" value="SELF_OWNED"/><el-option label="外部反向代理" value="EXTERNAL_PROXY"/></el-select><el-select v-model="q.status" placeholder="状态" clearable><el-option v-for="x in ['PENDING','ACTIVE','SUSPENDED','EXPIRED','TERMINATED','PROVISION_FAILED']" :key="x" :label="x" :value="x"/></el-select><el-button type="primary" @click="q.page=1;load()">查询</el-button></div><el-table :data="rows" v-loading="loading" stripe><el-table-column label="服务号" width="185"><template #default="s"><el-button type="primary" link @click="router.push('/services/'+s.row.id)">{{s.row.service_no}}</el-button></template></el-table-column><el-table-column prop="customer_name" label="客户" min-width="140"/><el-table-column prop="product_name" label="产品" min-width="140"/><el-table-column prop="product_type" label="类型" width="115"/><el-table-column prop="package_name" label="套餐" min-width="120"/><el-table-column label="交付方式" width="130"><template #default="s"><el-tag :type="s.row.delivery_mode==='EXTERNAL_PROXY'?'warning':'success'">{{s.row.delivery_mode==='EXTERNAL_PROXY'?'外部反向代理':'自有资源'}}</el-tag></template></el-table-column><el-table-column prop="resource_summary" label="资源/代理" min-width="180"/><el-table-column prop="status" label="状态" width="130"/><el-table-column prop="expire_at" label="到期时间" width="180"/><el-table-column label="操作" width="290" fixed="right"><template #default="s"><el-button link type="primary" @click="router.push(`/services/${s.row.id}`)">详情</el-button><el-button v-if="auth.hasPermission('service:change')&&auth.hasPermission('service:status')&&s.row.status==='ACTIVE'" link @click="preview(s.row,'suspend')">暂停</el-button><el-button v-if="auth.hasPermission('service:change')&&auth.hasPermission('service:status')&&s.row.status==='SUSPENDED'" link type="success" @click="preview(s.row,'resume')">恢复</el-button><el-button v-if="auth.hasPermission('service:change')&&auth.hasPermission('service:renew')&&!['TERMINATED','PROVISION_FAILED'].includes(s.row.status)" link @click="preview(s.row,'renew')">续费</el-button><el-button v-if="auth.hasPermission('service:change')&&auth.hasPermission('service:status')&&s.row.status!=='TERMINATED'" link type="danger" @click="preview(s.row,'terminate')">终止</el-button></template></el-table-column></el-table><div class="pager"><el-pagination v-model:current-page="q.page" v-model:page-size="q.size" :total="total" layout="total,sizes,prev,pager,next" @change="load"/></div></el-card></div></template>
<style scoped>.page{display:grid;gap:16px}.head{display:flex;justify-content:space-between}.head h2{margin:0 0 6px}.head p{margin:0;color:#7b8494}.filters{display:flex;gap:10px;margin-bottom:14px;flex-wrap:wrap}.filters .el-input,.filters .el-select{max-width:220px}.pager{display:flex;justify-content:flex-end;margin-top:14px}</style>
